 private static final BlockPos BASE=new BlockPos(9100,100,9100);private static int checks,ticks;private static boolean reading;private static BlockPos tracked;private static final List<ItemStack> drops=new ArrayList<>();
 private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Canonical Storage: "+why);}
 private static ResourceLocation id(){return ResourceLocation.parse("vandorlabs:programmable_storage");}
 private static NativeStorageBlock block(){var value=BuiltInRegistries.BLOCK.get(id());need(value instanceof NativeStorageBlock,"public block installed");return (NativeStorageBlock)value;}
 private static NativeStorageItem item(){var value=BuiltInRegistries.ITEM.get(id());need(value instanceof NativeStorageItem,"public specialized item installed");return (NativeStorageItem)value;}
 private static NativeStorageEntity at(ServerLevel w,BlockPos pos){return (NativeStorageEntity)w.getBlockEntity(pos);}
 private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {private int window=700;Actor(ServerLevel w){super(w,new com.mojang.authlib.GameProfile(UUID.fromString("19bcd8bd-14d2-407f-9c3a-f08531f65340"),"CanonicalStorage"));getInventory().selected=0;setGameMode(GameType.SURVIVAL);}
  @Override public OptionalInt openMenu(MenuProvider provider){return openMenu(provider,buffer->{});}
  @Override public OptionalInt openMenu(MenuProvider provider,java.util.function.Consumer<net.minecraft.network.RegistryFriendlyByteBuf> writer){containerMenu=provider.createMenu(++window,getInventory(),this);if(containerMenu instanceof NativeStorageMenu){var buffer=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),serverLevel().registryAccess());try{writer.accept(buffer);need(buffer.readBlockPos().equals(((NativeStorageMenu)containerMenu).tile.getBlockPos())&&!buffer.isReadable(),"canonical dedicated opening body");}finally{buffer.release();}}return OptionalInt.of(window);}
 }
 private static ItemStack configured(){var stack=new ItemStack(item(),2);var tag=new CompoundTag();NativeStorageSettings.fresh().write(tag);tag.putInt("housingTexture",296);tag.putInt("MainTextureLayout",2);tag.putString("SourcePrivate","retained");var list=new ListTag();for(int slot:new int[]{0,26}){var row=new CompoundTag();row.putByte("Slot",(byte)slot);row.putString("id",slot==0?"minecraft:iron_ingot":"minecraft:diamond");row.putByte("Count",(byte)(slot==0?4:7));row.putShort("Damage",(short)0);list.add(row);}tag.put("Items",list);var root=new CompoundTag();root.put("BlockEntityTag",tag);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(root));return stack;}
 private static NativeStorageEntity place(ServerLevel w,Actor actor,BlockPos pos,int facing){w.getChunkAt(pos);w.setBlock(pos,Blocks.AIR.defaultBlockState(),18);w.setBlock(pos.below(),Blocks.STONE.defaultBlockState(),18);actor.setPos(pos.getX()+.5,pos.getY(),pos.getZ()-2);actor.setYRot(Direction.from2DDataValue(facing).toYRot());actor.setShiftKeyDown(false);actor.setGameMode(GameType.SURVIVAL);var stack=configured();actor.setItemInHand(InteractionHand.MAIN_HAND,stack);need(actor.gameMode.useItemOn(actor,w,stack,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(pos.getX()+.5,pos.getY(),pos.getZ()+.5),Direction.UP,pos.below(),false)).consumesAction()&&stack.getCount()==1,"actual public Survival placement consumes one");var owner=at(w,pos);need(owner!=null&&owner.getType()==BuiltInRegistries.BLOCK_ENTITY_TYPE.get(id())&&!owner.inert(),"canonical entity factory");need(owner.getBlockState().getValue(NativeStorageBlock.FACING)==Direction.from2DDataValue(facing).getOpposite(),"actual placement facing");need(owner.settings().housing().mainTexture==296&&owner.settings().housing().layout()==2&&owner.getItem(0).getCount()==4&&owner.getItem(26).getCount()==7,"source choices/all27 slot envelope installed");for(Direction side:Direction.values()){var cap=w.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,pos,side);need(cap!=null&&cap.getSlots()==27&&cap.getStackInSlot(26).getCount()==7,"production capability every side");}need(!owner.getUpdateTag(w.registryAccess()).contains("Items")&&!owner.getUpdateTag(w.registryAccess()).contains("SourcePrivate"),"public projection inventory/private free");var pick=block().getCloneItemStack(owner.getBlockState(),new BlockHitResult(Vec3.atCenterOf(pos),Direction.NORTH,pos,false),w,pos,actor);need(pick.is(item())&&!NativeStorageItemSettings.configuration(pick).contains("Items")&&NativeStorageItemSettings.configuration(pick).getInt("housingTexture")==296,"configured pick preserves appearance without27 stacks");return owner;}
 @SubscribeEvent public static void drop(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent e){if(tracked!=null&&e.getEntity() instanceof ItemEntity item&&item.position().distanceToSqr(Vec3.atCenterOf(tracked))<16){drops.add(item.getItem().copy());e.setCanceled(true);}}
 private static void mining(ServerLevel w,Actor actor){for(boolean inert:new boolean[]{false,true})for(int mode=0;mode<4;mode++){var pos=BASE.east(80+mode*3+(inert?24:0));var owner=place(w,actor,pos,mode);CompoundTag original=null;if(inert){original=owner.saveWithoutMetadata(w.registryAccess());original.putInt(NativeStorageEntity.SCHEMA,99);original.putByteArray("UnknownOwner",new byte[]{3,1,4,1,5});owner.loadWithComponents(original,w.registryAccess());need(owner.inert(),"unsupported snapshot refuses");}actor.setGameMode(mode>=2?GameType.CREATIVE:GameType.SURVIVAL);actor.setItemInHand(InteractionHand.MAIN_HAND,mode%2==0?new ItemStack(Items.IRON_PICKAXE):new ItemStack(Items.WOODEN_PICKAXE));tracked=pos;drops.clear();need(actor.gameMode.destroyBlock(pos)&&w.getBlockState(pos).isAir(),"actual canonical removal mode="+mode+" inert="+inert);int blocks=drops.stream().filter(s->s.is(item())).mapToInt(ItemStack::getCount).sum(),diamonds=drops.stream().filter(s->s.is(Items.DIAMOND)).mapToInt(ItemStack::getCount).sum(),iron=drops.stream().filter(s->s.is(Items.IRON_INGOT)).mapToInt(ItemStack::getCount).sum();need(blocks==(inert||mode==0?1:0)&&diamonds==(inert?0:7)&&iron==(inert?0:4),"single owner/proper-wrong-creative counts mode="+mode+" inert="+inert+" drops="+drops);if(inert){var recovery=drops.stream().filter(s->s.is(item())).findFirst().orElseThrow();need(NativeStorageItemSettings.configuration(recovery).getCompound(NativeStorageEntity.RECOVERY).equals(original),"sole recovery retains complete old snapshot");var before=recovery.copy();var target=pos.above(4);w.setBlock(target.below(),Blocks.STONE.defaultBlockState(),18);actor.setGameMode(GameType.SURVIVAL);actor.setItemInHand(InteractionHand.MAIN_HAND,recovery);actor.gameMode.useItemOn(actor,w,recovery,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(target.below()),Direction.UP,target.below(),false));need(w.getBlockState(target).isAir()&&ItemStack.isSameItemSameComponents(before,recovery)&&before.getCount()==recovery.getCount(),"recovery cannot mint another usable owner");}tracked=null;}}
 private static void recipes(ServerLevel w){var input=CraftingInput.of(2,1,List.of(new ItemStack(Items.CHEST),new ItemStack(VandorLabsBootstrap.PROGRAMMABLE_ITEM.get())));var recipe=(CraftingRecipe)w.getRecipeManager().byKey(id()).orElseThrow().value();need(recipe.matches(input,w)&&recipe.assemble(input,w.registryAccess()).is(item())&&recipe.assemble(input,w.registryAccess()).getCount()==1,"actual released shapeless recipe result");}
 private static void saved(ServerLevel w){var owner=at(w,BASE);need(owner!=null&&!owner.inert()&&owner.getItem(26).getCount()==7&&owner.settings().housing().mainTexture==296,"saved canonical live inventory/settings");var raw=owner.saveWithFullMetadata(w.registryAccess());need(raw.getString("id").equals(id().toString())&&raw.getString("SourcePrivate").equals("retained")&&raw.getCompound("NeoForgeData").getString("Owner").equals("canonical:live"),"canonical identity/private/platform persistence");var inert=at(w,BASE.east(8));need(inert!=null&&inert.inert()&&inert.getItem(26).isEmpty()&&inert.saveWithoutMetadata(w.registryAccess()).getByteArray("UnknownOwner").length==5,"saved exact inert ownership remains unavailable");var old=at(w,BASE.east(16));need(old!=null&&old.settings().housing().mainTexture==294,"previous raw empty-NBT factory palette preserved");}
 @SubscribeEvent public static void started(net.neoforged.neoforge.event.server.ServerStartedEvent event){String phase=System.getProperty("vandorlabs.transmitterPhase","");if(!phase.startsWith("storage-canonical-"))return;var server=event.getServer();System.out.println("[vandorlabs][storage-canonical] actual server PID="+ProcessHandle.current().pid());try{var w=server.overworld();var b=block();var state=b.defaultBlockState();need(state.getDestroySpeed(w,BASE)==5&&b.getExplosionResistance()==6&&state.requiresCorrectToolForDrops()&&state.is(net.minecraft.tags.BlockTags.MINEABLE_WITH_PICKAXE)&&state.is(net.minecraft.tags.BlockTags.NEEDS_STONE_TOOL),"Source hardness/effectiveblast/harvest contract");need(item().getDescriptionId().equals("block.vandorlabs.programmable_storage"),"canonical name key");recipes(w);for(int x:new int[]{0,8,16}){var p=BASE.east(x);w.setChunkForced(p.getX()>>4,p.getZ()>>4,true);w.getChunkAt(p);}if(phase.endsWith("read")){reading=true;return;}var actor=new Actor(w);for(int facing=0;facing<4;facing++)place(w,actor,BASE.east(200+facing*3),facing);for(int meta=0;meta<32;meta++){Direction raw=Direction.from3DDataValue(meta&7);need(b.legacyState(meta).getValue(NativeStorageBlock.FACING)==(raw.getAxis().isHorizontal()?raw:Direction.NORTH),"previous metadata "+meta);}mining(w,actor);var owner=place(w,actor,BASE,0);owner.getPersistentData().putString("Owner","canonical:live");actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(VandorLabsBootstrap.CONFIGURIZER.get()));var hit=new BlockHitResult(Vec3.atCenterOf(BASE),Direction.NORTH,BASE,false);need(actor.getMainHandItem().useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,hit)).consumesAction()&&actor.containerMenu instanceof NativeStorageMenu,"global Configurizer dedicated dialog");var edit=NativeStorageEdit.from(BASE,actor.containerMenu.containerId,owner.visual().appearance());need(!NativeStorageMenu.apply(actor,new NativeStorageEdit(BASE,edit.window()+1,295,0,false,new int[]{-1,-1,-1,-1,-1,-1})),"stale public window rejected");actor.closeContainer();actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);need(actor.gameMode.useItemOn(actor,w,ItemStack.EMPTY,InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.containerMenu instanceof ChestMenu&&actor.containerMenu.slots.size()==63,"ordinary public27slot inventory");actor.closeContainer();w.setBlock(BASE.east(8),b.defaultBlockState(),18);var bad=new CompoundTag();bad.putInt(NativeStorageEntity.SCHEMA,99);bad.putByteArray("UnknownOwner",new byte[]{3,1,4,1,5});at(w,BASE.east(8)).loadWithComponents(bad,w.registryAccess());w.setBlock(BASE.east(16),b.defaultBlockState(),18);at(w,BASE.east(16)).loadWithComponents(new CompoundTag(),w.registryAccess());saved(w);server.saveEverything(true,true,true);System.out.println("[vandorlabs][storage-canonical] write PASS checks="+checks);}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][storage-canonical] FAIL "+failure);}finally{if(!reading)server.halt(false);}}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.LevelTickEvent.Post event){if(!reading||!(event.getLevel() instanceof ServerLevel w)||w!=w.getServer().overworld())return;try{need(++ticks<100,"restart preparation deadline");if(at(w,BASE)==null||at(w,BASE.east(8))==null||at(w,BASE.east(16))==null)return;saved(w);w.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][storage-canonical] read PASS checks="+checks);reading=false;w.getServer().halt(false);}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][storage-canonical] FAIL "+failure);reading=false;w.getServer().halt(false);}}
